use std::io::{self, BufRead, Write};

// works with files, stdin, sockets and in-memory data alike
fn number_lines<R: BufRead, W: Write>(input: R, mut out: W) -> io::Result<usize> {
    let mut count = 0;
    for line in input.lines() {
        let line = line?;
        count += 1;
        writeln!(out, "{count:>3}: {line}")?;
    }
    Ok(count)
}

fn main() -> io::Result<()> {
    let text = "fn main() {\n    println!(\"hi\");\n}\n";
    let mut output: Vec<u8> = Vec::new();
    let n = number_lines(text.as_bytes(), &mut output)?;
    print!("{}", String::from_utf8_lossy(&output));
    println!("{n} lines");

    let stdout = io::stdout();
    let handle = stdout.lock();
    number_lines(io::Cursor::new("one\ntwo"), handle)?;
    Ok(())
}

