use std::fs;
use std::io;

fn main() -> io::Result<()> {
    let root = std::env::temp_dir().join(format!("rust-course-dir-{}", std::process::id()));
    fs::create_dir_all(root.join("src/bin"))?;
    fs::write(root.join("Cargo.toml"), "[package]\n")?;
    fs::write(root.join("src/main.rs"), "fn main() {}\n")?;

    let mut names: Vec<String> = Vec::new();
    for entry in fs::read_dir(&root)? {
        let entry = entry?;
        let kind = if entry.file_type()?.is_dir() { "dir " } else { "file" };
        names.push(format!("{kind} {}", entry.file_name().to_string_lossy()));
    }
    names.sort(); // read_dir has no guaranteed order
    for n in &names {
        println!("{n}");
    }

    let text = fs::read_to_string(root.join("src/main.rs"))?;
    println!("main.rs: {}", text.trim());

    fs::remove_dir_all(&root)?;
    Ok(())
}

