use std::fs;
use std::io::ErrorKind;

fn load_or_default(path: &str) -> String {
    match fs::read_to_string(path) {
        Ok(text) => text,
        Err(e) if e.kind() == ErrorKind::NotFound => String::from("(defaults)"),
        Err(e) => panic!("cannot read {path}: {e}"),
    }
}

fn main() {
    println!("{}", load_or_default("/definitely/not/here.toml"));
    let e = fs::File::open("/definitely/not/here.toml").unwrap_err();
    println!("{:?}: {}", e.kind(), e);
}

